const $=id=>document.getElementById(id);
const params=new URLSearchParams(location.search);
const inviteToken=params.get('invite');
const steps=['Your details','Plan & price','Agreement','Payment'];
let enrollment=null;
let appMode='mock';
let customerStep=0;
let viewStep=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatUsd=value=>value==null||value===''?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(value));
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
function message(id,text,error=false){const el=$(id);el.textContent=text;el.classList.toggle('error',error);el.hidden=!text}
function reportStepError(error){message('step-alert',error.message,true);if(/vessel value/i.test(error.message)){const input=$('value');if(input){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','value-hint step-alert');input.focus();}}}
const paymentStatusLabel=status=>({not_started:'Not started',pending:'Payment pending',succeeded:'Payment received',failed:'Last checkout failed',abandoned:'Checkout abandoned',canceled_simulated:'Canceled after HYC decline'})[status]||'Payment status needs review';
const customerSignatureLabel=status=>({pending:'Awaiting customer signature',signed_simulated:'Signed by customer (simulation)',provider_confirmed:'Signed by customer (SignWell confirmed)'})[status]||'Signature status needs review';
const serviceReadinessLabel=status=>({not_started:'Setup not started',boat_binder_pending:'Boat Binder setup pending',operational_onboarding_pending:'Operational onboarding pending',ready_to_schedule:'Ready to schedule',scheduled:'Initial visit scheduled'})[status]||'Service readiness needs review';
const eligibilityLabel=status=>({not_required:'No additional review required',review_required:'Review required',reviewed_eligible:'Reviewed eligible',exception_approved:'Exception approved'})[status]||'Review status needs a manual check';
function applyModeCopy(){const testMode=appMode==='signwell-test';$('admin-mode-label').textContent=testMode?'LOCAL CAPTAIN CONSOLE · SIGNWELL TEST MODE':'LOCAL CAPTAIN CONSOLE · MOCK MODE';$('customer-mode-label').textContent=testMode?'PRIVATE CAPTAIN INVITATION · SIGNWELL TEST MODE':'PRIVATE CAPTAIN INVITATION · LOCAL MOCK';$('mode-notice').textContent=testMode?'SIGNWELL TEST MODE — synthetic enrollment only. SignWell may attempt provider notifications. Payments are simulated; documents are not legally binding. No production signing or Stripe payments.':'MOCK MODE — synthetic enrollment only. No provider requests or email are sent. Payments are simulated; documents are not legally binding.';}
function showAdmin(){ $('admin-view').hidden=false;$('customer-view').hidden=true;api('/api/config').then(c=>{appMode=c.mode;applyModeCopy();loadQueue();}).catch(()=>{applyModeCopy();loadQueue();}); }
function showCustomer(){ $('admin-view').hidden=true;$('customer-view').hidden=false; }

$('new-invite').addEventListener('click',async()=>{try{const r=await api('/api/admin/invitations','POST',{});const url=new URL(r.inviteUrl,location.origin).href;$('invite-result').hidden=false;$('invite-result').innerHTML=`<h2>Invitation ready</h2><p>Local invitation created. No email was sent.</p><label for="invite-link">Copy this customer link</label><input id="invite-link" class="invite-url" readonly value="${esc(url)}"><div class="actions"><button id="copy-link" class="secondary">Copy invitation link</button><a class="button primary" href="${esc(url)}" target="_blank" rel="noopener">Open customer view</a></div>`;$('copy-link').onclick=async()=>{await navigator.clipboard.writeText(url);message('admin-message','Invitation link copied.');};message('admin-message','Invitation created for captain-invited enrollment.');}catch(e){message('admin-message',e.message,true);}});
$('refresh').addEventListener('click',loadQueue);

async function loadQueue(){try{const all=await api('/api/admin/enrollments');const queue=$('queue');if(!all.length){queue.innerHTML='<p class="lede">No enrollments yet. Create an invitation to start a synthetic customer flow.</p>';return;}queue.innerHTML=all.slice().reverse().map(e=>`<article class="queue-item"><div><h3>${esc(e.questionnaire?.ownerName||'Invited customer')}</h3><div>${esc(e.questionnaire?.vesselName||'Vessel pending')} · ${esc(e.selection?.plan||'Plan pending')}</div><div class="workflow-status"><strong>${esc(e.workflowStatus?.label||'Enrollment in progress')}</strong><span>${esc(e.workflowStatus?.detail||'Enrollment status needs review.')}</span></div></div><button class="secondary" data-review="${esc(e.id)}">Open review</button></article>`).join('');queue.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openReview(b.dataset.review));}catch(e){message('admin-message',e.message,true);}}

async function openReview(id){
  try {
    const e=await api(`/api/admin/enrollments/${id}`),q=e.questionnaire||{},box=$('review');box.hidden=false;
    const workflow=e.workflowStatus||{label:'Enrollment in progress',detail:'Enrollment status needs review.'};
    const above=Number(q.value)>1500000;
    const dispositionRecorded=['reviewed_eligible','exception_approved'].includes(e.eligibilityReview);
    const eligibility=above?`<div class="warning"><b>${dispositionRecorded?'Internal eligibility disposition recorded':'Internal eligibility review required'}</b><p>${dispositionRecorded?'Captain Will recorded an internal disposition before signing.':'Record an internal disposition before Captain Will signs.'} Status: ${eligibilityLabel(e.eligibilityReview)}.</p></div>`:'';
    const eligibilityActions=above&&e.eligibilityReview==='review_required'?'<div class="review-actions"><button class="secondary" id="eligible">Reviewed eligible</button><button class="secondary" id="exception">Exception approved</button></div>':'';
    const reconciliation=e.internalReconciliationRequired?`<div class="warning"><b>Manual reconciliation required</b><p>SignWell confirmed Captain Will’s signature before internal eligibility approval. HYC acceptance and service readiness remain on hold.</p>${!above||['reviewed_eligible','exception_approved'].includes(e.eligibilityReview)?'<button class="secondary" id="reconcile-accept">Confirm manual reconciliation & accept</button>':''}</div>`:'';
    const inviteActions=e.inviteUrl?`<div class="review-actions"><button class="secondary" id="copy-review-invite">Copy Invitation Link</button><a class="button primary" href="${esc(e.inviteUrl)}" target="_blank" rel="noopener">Open Customer View</a></div>`:'';
    box.innerHTML=`<p class="eyebrow">CAPTAIN WILL REVIEW</p><h2>${esc(q.ownerName||'Customer')} · ${esc(q.vesselName||'Vessel')}</h2><div class="workflow-status primary-status"><strong>${esc(workflow.label)}</strong><span>${esc(workflow.detail)}</span></div>${inviteActions}${eligibility}${reconciliation}<dl class="summary"><dt>Contact</dt><dd>${esc(q.ownerEmail)} · ${esc(q.ownerPhone)}</dd><dt>Owner / contracting business</dt><dd>${esc(q.ownerName||'—')} · ${esc(q.businessName||'Individual / no business')}</dd><dt>Signer</dt><dd>${esc(q.signerName||'—')} ${esc(q.signerTitle||'')}</dd><dt>Vessel</dt><dd>${esc(q.vesselModel)} · ${esc(q.loa)} ft · ${formatUsd(q.value)} · HIN/Reg ${esc(q.hin||'—')}</dd><dt>Location</dt><dd>${esc(q.marina)} · ${esc(q.slip)}</dd><dt>Insurance</dt><dd>${esc(q.insurer)} · expires ${esc(q.policyExpiry)}</dd><dt>Hazards / restrictions</dt><dd>${esc(q.hazards||'None supplied')}</dd><dt>Service scope</dt><dd>${planSummary(e.selection?.plan)} Explicit permissions remain controlled by signed Exhibit A.</dd><dt>Emergency authority</dt><dd>Cap $0 · contact ${esc(q.emergencyName)} / ${esc(q.emergencyPhone)}</dd><dt>Plan / billing</dt><dd>${esc(e.selection?.plan)} · ${esc(e.selection?.visitFrequency)} visits · ${esc(e.selection?.cadence)} · $${esc(e.selection?.amount)} ${e.selection?.cadence==='Annual'?'per year':'per month'}</dd><dt>Payment</dt><dd>${paymentStatusLabel(e.paymentStatus)}${e.paidAt?` at ${esc(e.paidAt)}`:''} · next anniversary ${esc(e.nextBillingAt||'—')}</dd><dt>Customer signature</dt><dd>${customerSignatureLabel(e.signers.customer)}${e.signedAt?` at ${esc(e.signedAt)}`:''} · terms v${esc(e.signedAgreementVersion||'—')}</dd><dt>Agreement</dt><dd>TEST DOCUMENT — NOT LEGALLY BINDING · ${esc(e.signWellStatus||'Mock mode')}</dd></dl>${e.signingMode==='signwell-test'?`<div class="review-actions"><button class="secondary" id="refresh-signwell">Check SignWell status</button>${e.hycDecision==='accepted'?`<a class="button secondary" href="/api/admin/enrollments/${esc(id)}/signwell/pdf">Download completed test PDF</a>`:''}</div><div id="signwell-frame-admin" class="signwell-frame"></div>`:''}${e.hycDecision==='review_pending'&&e.paymentStatus==='succeeded'?`${eligibilityActions}${e.signingMode==='signwell-test'?`<div class="review-actions"><button class="primary" id="open-hyc-sign" ${above&&e.eligibilityReview==='review_required'?'disabled':''}>Review & sign with SignWell</button><button class="secondary" id="decline">Decline enrollment</button></div>`:`<div class="review-actions"><button class="primary" id="accept" ${above&&e.eligibilityReview==='review_required'?'disabled':''}>Countersign & accept</button><button class="secondary" id="decline">Decline enrollment</button></div>`}`:e.hycDecision==='accepted'?`<h3>Post-acceptance setup</h3><p>Keep Boat Binder, operational onboarding, and service scheduling separate.</p><label><input type="checkbox" data-ready="boatBinder" ${e.boatBinder?'checked':''}> Boat Binder setup complete</label><br><label><input type="checkbox" data-ready="operationalOnboarding" ${e.operationalOnboarding?'checked':''}> Operational onboarding complete</label><br><label><input type="checkbox" data-ready="firstVisit" ${e.firstVisit?'checked':''}> First visit scheduled</label><p>Readiness: <strong>${serviceReadinessLabel(e.serviceReadiness)}</strong></p>`:''}`;
    if($('accept'))$('accept').onclick=()=>decide(id,'accept');if($('decline'))$('decline').onclick=()=>decide(id,'decline');if($('refresh-signwell'))$('refresh-signwell').onclick=()=>checkCaptainStatus(id);if($('open-hyc-sign'))$('open-hyc-sign').onclick=()=>openCaptainSigning(id);
    if($('copy-review-invite'))$('copy-review-invite').onclick=async()=>{const link=new URL(e.inviteUrl,location.origin).href;await navigator.clipboard.writeText(link);message('admin-message','Invitation link copied; it reopens this same enrollment.');};
    if($('eligible'))$('eligible').onclick=()=>setEligibility(id,'reviewed_eligible');if($('exception'))$('exception').onclick=()=>setEligibility(id,'exception_approved');if($('reconcile-accept'))$('reconcile-accept').onclick=()=>reconcileAcceptance(id);
    box.querySelectorAll('[data-ready]').forEach(c=>c.onchange=()=>setReady(id,c.dataset.ready,c.checked));box.scrollIntoView({behavior:'smooth',block:'start'});
  }catch(e){message('admin-message',e.message,true);}
}
async function decide(id,decision){try{await api(`/api/admin/enrollments/${id}/${enrollmentMode(id)}`,'POST',{decision});message('admin-message',decision==='accept'?'HYC acceptance and simulated countersignature recorded.':'Decline recorded; simulated cancellation and manual-refund-pending created.');await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}
function enrollmentMode(id){const card=document.querySelector(`[data-current-enrollment="${CSS.escape(id)}"]`);return appMode==='signwell-test'?'signwell/decision':'decision';}
async function checkCaptainStatus(id){try{await api(`/api/admin/enrollments/${id}/signwell/status`,'POST',{});message('admin-message','SignWell status refreshed from the provider.');await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}
async function openCaptainSigning(id){try{const {signingUrl}=await api(`/api/admin/enrollments/${id}/signwell/signing`);if(!window.SignWellEmbed){await new Promise((resolve,reject)=>{let script=document.querySelector('script[data-signwell-embed]');if(!script){script=document.createElement('script');script.src='https://static.signwell.com/assets/embedded.js';script.dataset.signwellEmbed='true';script.onload=resolve;script.onerror=()=>reject(new Error('SignWell signing interface could not be loaded.'));document.head.append(script);}else if(window.SignWellEmbed)resolve();else{script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>reject(new Error('SignWell signing interface could not be loaded.')),{once:true});}});}new SignWellEmbed({url:signingUrl,containerId:'signwell-frame-admin',allowClose:true,allowDecline:true,allowRedirect:false,events:{completed:()=>checkCaptainStatus(id),declined:()=>checkCaptainStatus(id),closed:()=>checkCaptainStatus(id),error:()=>message('admin-message','SignWell could not complete the signing session. Check provider status.',true)}}).open();}catch(e){message('admin-message',e.message,true);}}
async function setEligibility(id,disposition){try{await api(`/api/admin/enrollments/${id}/eligibility`,'POST',{disposition});message('admin-message',`Eligibility marked ${disposition.replaceAll('_',' ')}.`);await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}
async function reconcileAcceptance(id){try{await api(`/api/admin/enrollments/${id}/signwell/reconcile`,'POST',{decision:'accept'});message('admin-message','Manual provider signature reconciliation recorded; HYC acceptance confirmed.');await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}
async function setReady(id,step,done){try{await api(`/api/admin/enrollments/${id}/readiness`,'POST',{step,done});await loadQueue();await openReview(id);}catch(e){message('admin-message',e.message,true);}}

function stepBar(){ $('progress').innerHTML=steps.map((s,i)=>`<span ${i===customerStep?'aria-current="step"':''}>${i+1}. ${s}</span>`).join(''); }
function questionnaireForm(){const q=enrollment.questionnaire||{};return `<h2>Your Details</h2><p>Use fictional details in this prototype. Owner, optional contracting business, and signer are captured separately.</p><form id="questionnaire" class="form-grid">
<section class="field-group full"><h3>Owner &amp; Contact</h3><div class="group-fields">${field('ownerName','Owner Name','text',true,false,q.ownerName)}${field('businessName','Business Name (if applicable)','text',false,false,q.businessName)}${field('signerName','Person signing this agreement','text',true,false,q.signerName||q.ownerName)}${field('signerTitle','Signer title (if applicable)','text',false,false,q.signerTitle)}${field('ownerEmail','Owner email','email',true,false,q.ownerEmail)}${field('ownerPhone','Owner phone','tel',true,false,q.ownerPhone)}</div></section>
<section class="field-group full"><h3>Vessel &amp; Location</h3><div class="group-fields">${field('vesselName','Vessel name','text',true,false,q.vesselName)}${field('vesselModel','Year / make / model','text',true,false,q.vesselModel)}${field('loa','Length overall (30–60 ft)','number',true,false,q.loa)}${field('value','Approximate vessel value','text',true,false,q.value)}${field('hin','HIN / Registration Number','text',true,false,q.hin)}${field('marina','Marina','text',true,false,q.marina)}${field('slip','Dock / slip','text',true,false,q.slip)}</div></section>
<section class="field-group full"><h3>Insurance</h3><div class="group-fields">${field('insurer','Marine insurer','text',true,false,q.insurer)}${field('policyExpiry','Policy expiration','date',true,false,q.policyExpiry)}</div></section>
<section class="field-group full"><h3>Emergency Contact</h3><div class="group-fields">${field('emergencyName','Emergency contact name','text',true,false,q.emergencyName)}${field('emergencyPhone','Emergency contact phone','tel',true,false,q.emergencyPhone)}</div></section>
${field('hazards','Access limitations, hazards, and do-not-operate notes','textarea',false,true,q.hazards)}<div class="warning field full">Do not enter access codes, alarm PINs, passwords, payment card data, or real customer information.</div>
<div class="field full confirm-row"><input id="confirmAuthority" type="checkbox" name="confirmAuthority" required ${q.confirmAuthority?'checked':''}><label for="confirmAuthority">I confirm I own the vessel or am authorized to enter into this agreement on the owner's behalf.</label></div><div class="field full confirm-row"><input id="insuranceConfirmed" type="checkbox" name="insuranceConfirmed" required ${q.insuranceConfirmed?'checked':''}><label for="insuranceConfirmed">I confirm current appropriate marine insurance is maintained and proof can be provided on request.</label></div><div class="actions field full"><button class="primary">Continue to plan & pricing</button></div></form>`;}
function field(name,label,type,required,full=false,current=''){const v=esc(name==='value'&&current!==''?Number(current).toLocaleString('en-US',{maximumFractionDigits:2}):current);return `<div class="field ${full?'full':''}"><label for="${name}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="${name}" name="${name}" ${required?'required':''}>${v}</textarea>`:name==='value'?`<div class="currency-input"><span aria-hidden="true">$</span><input id="${name}" name="${name}" type="text" inputmode="decimal" autocomplete="off" value="${v}" required aria-describedby="value-hint"></div><small id="value-hint">For example: 850,000, 850k, or 1.5 million.</small>`:`<input id="${name}" name="${name}" type="${type}" value="${v}" ${required?'required':''} ${type==='number'?(name==='loa'?'min="30" max="60" step="1"':'min="0" step="1"'):''}>`}</div>`;}
function planSummary(plan){return ({'Dock Check':'Dockside visual check only; no boarding or equipment operation.','Dock Watch':'Scheduled visual vessel and system checks as listed in Exhibit A. Equipment actions require separate explicit authorization.','Dock Watch Plus':'Dock Watch checks plus engine visual checks; engine starts only if the specific equipment and limits are expressly authorized in Exhibit A.'})[plan]||'Included activities are set by the service plan and signed Exhibit A. No equipment operation is implied.';}
function planForm(){const s=enrollment.selection||{};return `<h2>Plan &amp; Price</h2><form id="plan-form" class="form-grid"><div class="field"><label for="plan">Plan</label><select id="plan" name="plan"><option ${s.plan==='Dock Check'?'selected':''}>Dock Check</option><option ${s.plan==='Dock Watch'?'selected':''}>Dock Watch</option><option ${s.plan==='Dock Watch Plus'?'selected':''}>Dock Watch Plus</option></select></div><div class="field"><label for="frequency">Visit frequency</label><select id="frequency" name="frequency"></select></div><div class="field"><label for="billing">Billing interval</label><select id="billing" name="billing"><option ${s.cadence==='Monthly'?'selected':''}>Monthly</option><option ${s.cadence==='Annual'?'selected':''}>Annual</option></select></div><div class="field full"><label>Included activity summary</label><p id="scope-preview"></p><small>Summary only. The signed Exhibit A controls service authorization. Plan selection alone does not authorize engine, generator, pump, or other equipment operation.</small></div><div class="field full"><label>Price preview</label><p id="price-preview" class="price"></p><small>Annual billing is prepaid at 10% off twelve monthly equivalents. Anniversary billing follows the first successful simulated charge.</small></div><div class="actions field full"><button class="secondary" type="button" id="back-details">Back to Your Details</button><button class="primary">Continue to Agreement Review</button></div></form>`;}
function agreementView(readOnly=false){const q=enrollment.questionnaire,p=enrollment.selection;const providerMode=appMode==='signwell-test';return `<h2>Agreement Review</h2><div class="terms"><p class="terms-stamp">TEST DOCUMENT — NOT LEGALLY BINDING</p><h3>Hayes Yacht Company · Sample Vessel Watch Agreement</h3><p>This fictional preview is only a workflow demonstration, not an HYC offer or contract.</p><p><b>Owner:</b> ${esc(q.ownerName)}<br><b>Contracting business:</b> ${esc(q.businessName||'Individual owner')}<br><b>Person signing:</b> ${esc(q.signerName)} ${esc(q.signerTitle||'')}<br><b>Owner email:</b> ${esc(q.ownerEmail)}<br><b>Vessel:</b> ${esc(q.vesselName)}, ${esc(q.vesselModel)}, ${esc(q.loa)} ft<br><b>Approximate vessel value:</b> ${formatUsd(q.value)}<br><b>HIN / registration:</b> ${esc(q.hin)}<br><b>Plan:</b> ${esc(p.plan)} · ${esc(p.visitFrequency)} visits · ${esc(p.cadence)} billing<br><b>Included activity summary:</b> ${planSummary(p.plan)}<br><b>Simulated charge:</b> $${esc(p.amount)} ${p.cadence==='Annual'?'annual prepayment':'monthly'}<br><b>Emergency spending authority:</b> $0 unless separately authorized in Exhibit A.</p><p>Customer signs first. After signing, proceed to simulated checkout immediately. Captain Will reviews and countersigns afterward. Payment does not mean HYC has accepted or fully executed an agreement. No vessel operation or payment authorization is created.</p><p>Annual prepayment/refunds, service commencement, Effective Date, and HYC acceptance require legal review. Source agreement Section 10.4 remains unchanged in the separate review draft.</p><p class="terms-stamp">TEST DOCUMENT — NOT LEGALLY BINDING</p></div>${readOnly?`<div class="actions"><button class="secondary" id="return-payment">Return to payment/status</button></div>`:providerMode&&enrollment.signWellDocumentReady?`<div class="warning"><b>TEST DOCUMENT — NOT LEGALLY BINDING</b><p>SignWell Test Mode will sign this agreement version. Simulated checkout opens only after the server confirms the customer signature.</p></div><div class="actions"><button class="primary" id="open-customer-signing">Open SignWell test signing</button><button class="secondary" id="check-customer-signature">Check signature status</button></div><p id="signature-message" class="message" role="status" aria-live="polite" hidden></p><div id="signwell-frame" class="signwell-frame" aria-label="SignWell Test Mode signing document"></div>`:providerMode?`<form id="sign-form"><label><input required type="checkbox"> I reviewed this synthetic agreement and want to issue it for SignWell Test Mode signing.</label><div class="actions" style="margin-top:18px"><button class="secondary" type="button" id="back-plan">Edit Plan & Price</button><button class="primary">Issue test agreement and continue</button></div></form>`:`<form id="sign-form"><label><input required type="checkbox"> I reviewed this sample and want to simulate my customer signature.</label><div class="actions" style="margin-top:18px"><button class="secondary" type="button" id="back-plan">Edit Plan & Price</button><button class="primary">Simulate customer signature & continue</button></div></form>`}`;}
function paymentView(){return `<h2>Simulated subscription checkout</h2><div class="success"><b>Customer signature confirmed by ${appMode==='signwell-test'?'SignWell Test Mode':'mock mode'}.</b> You can finish payment in this same session. Captain Will's countersignature is pending and is not required to continue.</div><p class="price">$${esc(enrollment.selection.amount)} <small>${enrollment.selection.cadence==='Annual'?'annual prepaid':'monthly'}</small></p><p>Simulated payment only. No Stripe request or payment method is involved.</p><div class="actions"><button class="primary" data-payment="succeeded">Simulate successful payment</button><button class="secondary" data-payment="failed">Simulate failed payment</button><button class="secondary" data-payment="abandoned">Simulate checkout abandoned</button><button class="secondary" id="review-signed">Review signed agreement</button></div>${enrollment.paymentStatus==='failed'||enrollment.paymentStatus==='abandoned'?'<p class="message error">Payment did not complete. You can retry here without returning later.</p>':''}`;}
function statusView(){if(enrollment.customerOutcomeNotice)return `<h2>HYC is reviewing your enrollment</h2><div class="warning">${esc(enrollment.customerOutcomeNotice)}</div><div class="actions"><button id="refresh-customer" class="secondary">Refresh status</button></div>`;if(enrollment.hycDecision==='accepted')return `<h2>HYC accepted your enrollment</h2><div class="success">Your sample agreement is fully executed ${appMode==='signwell-test'?'in SignWell Test Mode':'in this simulation'}. Captain Will will follow up with Boat Binder setup, operational onboarding, and first-visit scheduling.</div><p>Service readiness: ${esc(enrollment.serviceReadiness)}. This is not a production confirmation.</p><div class="actions"><button id="review-status" class="secondary">Review signed agreement</button><button id="refresh-customer" class="secondary">Refresh status</button></div>`;if(enrollment.hycDecision==='declined')return `<h2>HYC did not accept this enrollment</h2><div class="warning">The simulated subscription was canceled. A manual refund is pending review; no refund has been issued.</div><div class="actions"><button id="review-status" class="secondary">Review signed agreement</button><button id="refresh-customer" class="secondary">Refresh status</button></div>`;if(['declined','expired'].includes(enrollment.agreementStatus))return `<h2>Enrollment ended before payment</h2><div class="warning">${esc(enrollment.customerOutcomeNotice||'The test agreement closed before payment. No payment was taken.')}</div><div class="actions"><button id="refresh-customer" class="secondary">Refresh status</button></div>`;return `<h2>Payment received</h2><div class="success"><b>Your payment step is complete. HYC review and Captain Will's countersignature are still pending.</b> Payment is recorded in this simulation; HYC has not yet accepted the enrollment.</div><p>Captain Will will review the information and sign second. You do not need to return to complete your portion.</p><p>Payment timestamp: ${esc(enrollment.paidAt)}<br>Next billing anniversary: ${esc(enrollment.nextBillingAt)}</p><div class="actions"><button id="review-status" class="secondary">Review signed agreement</button><button id="refresh-customer" class="secondary">Refresh HYC review status</button></div>`;}

async function loadCustomer(){showCustomer();try{const config=await api('/api/config');appMode=config.mode;applyModeCopy();enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}`);viewStep=enrollment.hycDecision==='accepted'||enrollment.hycDecision==='declined'||enrollment.signedAt?3:!enrollment.questionnaire?0:!enrollment.selection?1:2;renderCustomer();}catch(e){message('customer-alert',e.message,true);$('step-content').innerHTML='<p>This invitation is invalid or expired. Ask Captain Will for a new local invitation.</p>';}}
function renderCustomer(){message('customer-alert','');let content;if(enrollment.customerOutcomeNotice||enrollment.hycDecision==='accepted'||enrollment.hycDecision==='declined'||['declined','expired'].includes(enrollment.agreementStatus)){customerStep=3;content=statusView();}else if(enrollment.signedAt){if(viewStep===2){customerStep=2;content=agreementView(true);}else if(enrollment.paymentStatus==='succeeded'){customerStep=3;content=statusView();}else{customerStep=3;content=paymentView();}}else if(!enrollment.questionnaire){customerStep=0;viewStep=0;content=questionnaireForm();}else if(viewStep===0){customerStep=0;content=questionnaireForm();}else if(!enrollment.selection||viewStep===1){customerStep=1;content=planForm();}else{customerStep=2;content=agreementView();}$('progress').innerHTML=steps.map((s,i)=>`<span ${i===customerStep?'aria-current="step"':''}>${i+1}. ${s}</span>`).join('');$('step-content').innerHTML=`<div id="step-alert" class="message" role="alert" aria-live="polite" hidden></div>${content}`;bindCustomer();}

async function checkCustomerSignature(){try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/signature-status`,'POST',{});if(enrollment.signedAt){viewStep=3;renderCustomer();}else message('signature-message','SignWell has not confirmed your signature yet. You can keep this page open or check again.',false);}catch(e){message('signature-message',e.message,true);}}
async function openCustomerSigning(){try{const {signingUrl}=await api(`/api/invites/${encodeURIComponent(inviteToken)}/signing`);if(!window.SignWellEmbed){await new Promise((resolve,reject)=>{let script=document.querySelector('script[data-signwell-embed]');if(!script){script=document.createElement('script');script.src='https://static.signwell.com/assets/embedded.js';script.dataset.signwellEmbed='true';script.onload=resolve;script.onerror=()=>reject(new Error('SignWell signing interface could not be loaded.'));document.head.append(script);}else if(window.SignWellEmbed)resolve();else{script.addEventListener('load',resolve,{once:true});script.addEventListener('error',()=>reject(new Error('SignWell signing interface could not be loaded.')),{once:true});}});}new SignWellEmbed({url:signingUrl,containerId:'signwell-frame',allowClose:true,allowDecline:true,allowRedirect:false,events:{iframeLoaded:()=>message('signature-message','SignWell signing session opened. Continue when the agreement is visible.'),documentLoaded:()=>message('signature-message','SignWell agreement loaded.'),completed:()=>{message('signature-message','SignWell reported a signing event. Checking provider status…');checkCustomerSignature();},declined:()=>{message('signature-message','SignWell reported a decline. Checking provider status…',true);checkCustomerSignature();},closed:()=>{checkCustomerSignature();},error:()=>message('signature-message','SignWell could not complete the signing session. Check status or try again.',true)}}).open();}catch(e){message('signature-message',e.message,true);}}
function bindCustomer(){
const qform=$('questionnaire');if(qform)qform.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(qform);const body=Object.fromEntries(fd.entries());try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/questionnaire`,'POST',body);viewStep=1;renderCustomer();}catch(e){reportStepError(e);}};
if(qform){const owner=$('ownerName'),signer=$('signerName');let signerFollowsOwner=!signer.value||signer.value===owner.value;owner.addEventListener('input',()=>{if(signerFollowsOwner)signer.value=owner.value;});signer.addEventListener('input',()=>{signerFollowsOwner=signer.value===owner.value;});}
const pform=$('plan-form');if(pform){const frequency=$('frequency'),billing=$('billing'),plan=$('plan'),saved=enrollment.selection;const opts=()=>{const map={'Dock Check':['Every two weeks','Weekly'],'Dock Watch':['Monthly','Every two weeks','Weekly'],'Dock Watch Plus':['Weekly']};frequency.innerHTML=map[plan.value].map(x=>`<option ${saved?.visitFrequency===x?'selected':''}>${x}</option>`).join('');preview();};const preview=()=>{const band=Number(enrollment.questionnaire.loa)<=39?0:Number(enrollment.questionnaire.loa)<=49?1:2;const map={'Dock Check':{'Every two weeks':[99,99,99],Weekly:[159,159,159]},'Dock Watch':{Monthly:[129,149,169],'Every two weeks':[179,209,239],Weekly:[239,279,319]},'Dock Watch Plus':{Weekly:[399,449,499]}};const v=map[plan.value][frequency.value][band];$('price-preview').textContent=billing.value==='Annual'?`$${(v*12*.9).toFixed(2)} / year (10% off $${v}/mo)`:`$${v} / month`;$('scope-preview').textContent=planSummary(plan.value);};if(saved){plan.value=saved.plan;billing.value=saved.cadence;}plan.onchange=opts;frequency.onchange=preview;billing.onchange=preview;opts();$('back-details').onclick=()=>{viewStep=0;renderCustomer();};pform.onsubmit=async ev=>{ev.preventDefault();try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/plan`,'POST',{plan:plan.value,visitFrequency:frequency.value,billingCadence:billing.value});viewStep=2;renderCustomer();}catch(e){reportStepError(e);}};}
const sform=$('sign-form');if(sform)sform.onsubmit=async ev=>{ev.preventDefault();try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/sign`,'POST',{});if(appMode==='signwell-test'){message('step-alert','Test agreement issued. Open SignWell to sign; checkout stays locked until provider status confirms your signature.');renderCustomer();}else{viewStep=3;renderCustomer();}}catch(e){reportStepError(e);}};
if($('open-customer-signing'))$('open-customer-signing').onclick=()=>openCustomerSigning();if($('check-customer-signature'))$('check-customer-signature').onclick=()=>checkCustomerSignature();
document.querySelectorAll('[data-payment]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}/payment`,'POST',{outcome:b.dataset.payment});renderCustomer();}catch(e){reportStepError(e);b.disabled=false;}});
if($('back-plan'))$('back-plan').onclick=()=>{viewStep=1;renderCustomer();};if($('review-signed'))$('review-signed').onclick=()=>{viewStep=2;renderCustomer();};if($('return-payment'))$('return-payment').onclick=()=>{viewStep=3;renderCustomer();};if($('review-status'))$('review-status').onclick=()=>{viewStep=2;renderCustomer();};if($('refresh-customer'))$('refresh-customer').onclick=async()=>{try{enrollment=await api(`/api/invites/${encodeURIComponent(inviteToken)}`);renderCustomer();}catch(e){message('customer-alert',e.message,true);}};
}

if(inviteToken)loadCustomer();else showAdmin();
